import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.NPCRequest{EntityRuntimeID: 7, RequestType: packet.NPCRequestActionExecuteAction,
# CommandString: "/say hi", ActionType: 2, SceneName: "scene"}
EXECUTE_ACTION = bytes.fromhex("0701072f73617920686902057363656e65")

# generated by gophertunnel b8bd735:
# packet.NPCRequest{EntityRuntimeID: 300, RequestType: packet.NPCRequestActionExecuteOpeningCommands, ActionType: 200}
EMPTY_STRINGS = bytes.fromhex("ac020600c800")

GOLDENS = [
    pytest.param(
        v2225.NpcRequestPacket(
            id=7,
            type=v2225.NpcRequestPacket.RequestType.EXECUTE_ACTION,
            actions="/say hi",
            action_index=2,
            scene_name="scene",
        ),
        EXECUTE_ACTION,
        id="execute-action",
    ),
    pytest.param(
        v2225.NpcRequestPacket(
            id=300,
            type=v2225.NpcRequestPacket.RequestType.EXECUTE_OPENING_COMMANDS,
            action_index=200,
        ),
        EMPTY_STRINGS,
        id="empty-strings",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_npc_request_is_packet_98(version):
    assert version.PACKETS[98] is version.NpcRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_npc_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_npc_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
